<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue';
import {drafts,type PostStatus} from '../services/drafts';
import type {Entry} from '../services/publisher';
import UiButton from './UiButton.vue';
import UiIcon from './UiIcon.vue';
import UiDialog from './UiDialog.vue';
import UiTooltip from './UiTooltip.vue';
const props=defineProps<{entries:Entry[];openError:string}>();
const emit=defineEmits<{open:[post:PostStatus]}>();
const search=ref(''),platform=ref(''),language=ref(''),state=ref(''),offset=ref(0),rows=ref<PostStatus[]>([]),more=ref(false),busy=ref(false),error=ref(''),selected=ref<PostStatus|null>(null);
const platforms:Record<string,string>={youtube:'YouTube',tiktok:'TikTok',instagram:'Instagram',x:'X'};
const states:Record<string,string>={draft:'Draft',approved:'Approved',published:'Published',restricted:'Limited visibility',private:'Private video',inbox:'TikTok inbox',sending:'Sending',check:'Check result',failed:'Failed'};
const hints:Record<string,string>={draft:'Saved on this PC; no completed transfer is recorded for this file.',approved:'Approved locally. Nothing has been sent yet.',published:'The provider confirmed publishing. Later changes on the platform are not monitored.',restricted:'Posted with friends or followers visibility, not public visibility.',private:'Uploaded with private visibility.',inbox:'Delivered to TikTok’s inbox. Finish posting in TikTok.',sending:'A transfer is in progress. Do not resend it.',processing:'The provider is processing this video.',check:'The result is uncertain. Check the destination before allowing another attempt.',failed:'The provider confirmed that processing failed.',browser:'Opened in the browser. Publisher cannot confirm whether you posted there.'};
const filters=computed(()=>[platform.value,language.value,state.value].filter(Boolean).length);
let generation=0,timer:ReturnType<typeof setTimeout>|undefined;
async function load(){const request=++generation;busy.value=true;error.value='';try{const result=await drafts.statuses({search:search.value.trim(),platform:platform.value,language:language.value,state:state.value,offset:offset.value});if(request===generation){rows.value=result.items||[];more.value=result.more;}}catch(e){if(request===generation){error.value=String(e);rows.value=[];more.value=false}}finally{if(request===generation)busy.value=false}}
watch([search,platform,language,state],()=>{offset.value=0;clearTimeout(timer);++generation;busy.value=true;timer=setTimeout(load,200)});
function page(delta:number){offset.value=Math.max(0,offset.value+delta);void load()}
const title=(r:PostStatus)=>r.title||props.entries.find(e=>e.id===r.key.episode)?.title||r.key.episode;
const date=(s:string)=>new Date(s).toLocaleString([], {month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});
const canOpen=computed(()=>selected.value?.connected&&props.entries.some(e=>e.id===selected.value?.key.episode&&e.valid));
onMounted(load);onUnmounted(()=>{clearTimeout(timer);++generation});
</script>
<template>
 <main class="publisher-main posts-main">
  <header class="page-header"><h1>Posts</h1><UiTooltip text="Reload saved drafts and transfer results"><UiButton variant="quiet" :disabled="busy" aria-label="Refresh posts" @click="load"><UiIcon name="refresh"/></UiButton></UiTooltip></header>
  <div class="posts-toolbar"><input v-model="search" type="search" class="ui-field" placeholder="Search videos or accounts" aria-label="Search posts"><details><summary>Filters<span v-if="filters"> · {{filters}}</span></summary><div class="posts-filters"><select v-model="platform" class="ui-field" aria-label="Filter platform"><option value="">All platforms</option><option v-for="(label,id) in platforms" :value="id" :key="id">{{label}}</option></select><select v-model="language" class="ui-field" aria-label="Filter language"><option value="">Both languages</option><option value="es">Spanish</option><option value="en">English</option></select><select v-model="state" class="ui-field" aria-label="Filter status"><option value="">All statuses</option><option v-for="(label,id) in states" :value="id" :key="id">{{label}}</option></select><UiButton variant="quiet" @click="platform='';language='';state=''">Reset filters</UiButton></div></details></div>
  <p v-if="error||openError" class="notice error" role="alert">{{error||openError}}</p>
  <div class="posts-table-wrap" :aria-busy="busy"><table v-if="rows.length" class="posts-table"><thead><tr><th>Video</th><th>Account</th><th>Status</th><th>Updated</th></tr></thead><tbody><tr v-for="row in rows" :key="JSON.stringify(row.key)"><td><button class="post-title" @click="selected=row">{{title(row)}}</button><small>{{row.key.episode}}</small></td><td><span>{{row.accountName.replace(/^account:/,'')}}</span><small>{{platforms[row.key.platform]}} · {{row.key.language.toUpperCase()}}{{row.connected?'':' · Disconnected'}}</small></td><td><UiTooltip :text="hints[row.state]||'Check this result in the destination platform.'" :disabled="true"><span class="post-state" :class="'state-'+row.state">{{states[row.state]||'Check result'}}</span></UiTooltip></td><td><time :datetime="row.updatedAt">{{date(row.updatedAt)}}</time></td></tr></tbody></table></div>
  <p v-if="!rows.length&&!error" class="posts-empty" role="status">{{busy?'Loading posts…':search||filters?'No matching posts':'Your saved posts will appear here'}}</p>
  <footer class="posts-footer"><span>Saved on this PC</span><div v-if="offset||more"><UiButton variant="quiet" :disabled="busy||!offset" @click="page(-50)">Previous</UiButton><span>{{offset+1}}–{{offset+rows.length}}</span><UiButton variant="quiet" :disabled="busy||!more" @click="page(50)">Next</UiButton></div></footer>
  <UiDialog v-if="selected" :title="title(selected)" @close="selected=null"><p class="post-detail-account">{{platforms[selected.key.platform]}} / {{selected.accountName}} · {{selected.key.language.toUpperCase()}}</p><p class="post-detail-state">{{states[selected.state]||'Check result'}}</p><p class="muted">{{hints[selected.state]}}</p><dl class="post-details"><div><dt>Video version</dt><dd>{{selected.videoId}}</dd></div><div><dt>Last update</dt><dd>{{date(selected.updatedAt)}}</dd></div><div v-if="selected.reference"><dt>Reference</dt><dd class="mono">{{selected.reference}}</dd></div></dl><UiButton :disabled="!canOpen" @click="emit('open',selected)">Open post</UiButton><p v-if="!canOpen" class="muted">Reconnect this account and make the delivery available to edit this post.</p></UiDialog>
 </main>
</template>
<style scoped>
.posts-main{min-width:0}.posts-toolbar{display:flex;align-items:flex-start;gap:20px;margin-bottom:24px}.posts-toolbar>input{max-width:360px;width:100%}.posts-toolbar>details{flex:1;padding-top:12px}.posts-filters{display:flex;flex-wrap:wrap;gap:12px;padding-top:16px}.posts-filters select{min-width:180px}.posts-table-wrap{overflow-x:auto}.posts-table{width:100%;border-collapse:collapse;text-align:left;font-size:var(--text-sm)}.posts-table th{font-weight:400;color:var(--muted);padding:0 16px 12px 0}.posts-table td{padding:20px 16px 20px 0;border-top:1px solid var(--line);vertical-align:middle;max-width:300px;overflow-wrap:anywhere}.posts-table td:first-child{width:36%}.posts-table small{display:block;color:var(--muted);font-size:var(--text-xs);margin-top:4px}.post-title{border:0;background:none;color:var(--text);padding:0;text-align:left;font:inherit;cursor:pointer}.post-title:hover{text-decoration:underline}.posts-table time{font-size:var(--text-xs);color:var(--muted);white-space:nowrap}.post-state{white-space:nowrap}.state-published,.state-approved{color:var(--success)}.state-check{color:var(--warning)}.state-failed{color:var(--danger)}.posts-footer{display:flex;justify-content:space-between;align-items:center;margin-top:24px;color:var(--muted);font-size:var(--text-xs)}.posts-footer>div{display:flex;align-items:center;gap:12px}.posts-empty{padding:48px 0;color:var(--muted)}.post-detail-account{margin-bottom:24px}.post-detail-state{font-weight:500;margin-bottom:12px}.post-details{margin:24px 0}.post-details>div{display:flex;justify-content:space-between;gap:24px;padding:12px 0;border-top:1px solid var(--line)}.post-details dd{margin:0;overflow-wrap:anywhere;text-align:right}@media(max-width:900px){.posts-toolbar{flex-wrap:wrap}.posts-toolbar>details{flex-basis:100%}.posts-table th:last-child,.posts-table td:last-child{display:none}}
</style>
